DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT table_schema, table_name, column_name, pg_get_serial_sequence(table_schema || '.' || table_name, column_name) as seq
        FROM information_schema.columns
        WHERE column_default LIKE 'nextval%'
    ) LOOP
        IF r.seq IS NOT NULL THEN
            EXECUTE format('SELECT setval(%L, COALESCE((SELECT MAX(%I) FROM %I.%I), 1))', r.seq, r.column_name, r.table_schema, r.table_name);
        END IF;
    END LOOP;
END $$;
